// STRICTLY READ ONLY queries of live Production D1; user requested discrepancy investigation.
// No schema changes, metadata writes or production Worker deploy. No customer personal information.
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
const prodId='17e68a41-1d58-4a36-8a63-47c3e32443c4'
const mirrorId='0904a573-21ff-44d8-93b0-c9200f771702'
const config=readFileSync('wrangler.jsonc','utf8')
assert(config.includes('"name": "orders-app-branch2"')&&config.includes(mirrorId)&&!config.includes(prodId),'Audit must run on isolated branch, not main')
const account=process.env.CLOUDFLARE_ACCOUNT_ID,token=process.env.CLOUDFLARE_API_TOKEN
assert(account&&token,'Cloudflare credentials missing')
const base='https://api.cloudflare.com/client/v4/accounts/'+account+'/d1/database/'+prodId
const headers={Authorization:'Bearer '+token,'Content-Type':'application/json'}
const info=await fetch(base,{headers,signal:AbortSignal.timeout(20000)})
assert(info.ok,'Production D1 metadata unavailable')
assert.equal((await info.json()).result?.name,'orders_db_prod')
const queries=[{"name":"PROD_RETURN_RESERVATION_CONFLICTS","sql":"SELECT o.id AS order_id,o.external_id,o.shipping_status,ret.id AS return_id,ri.order_item_id,oi.product_name_snapshot,oi.stock_writeoff_status,ri.quantity AS returned_qty,ri.physical_tracking,ri.physical_received_at,ri.inventory_source,ir.status AS reservation_status,ir.quantity AS reservation_qty,ir.inventory_source AS reservation_source,ir.variant_id FROM return_items ri JOIN returns ret ON ret.id=ri.return_id JOIN orders o ON o.id=ret.order_id JOIN order_items oi ON oi.id=ri.order_item_id JOIN inventory_reservations ir ON ir.order_item_id=ri.order_item_id WHERE COALESCE(ret.status,'completed') <> 'cancelled' AND ri.quantity>0 AND ir.status IN ('active','unresolved') AND NOT EXISTS(SELECT 1 FROM exchanges ex WHERE ex.refund_return_id=ret.id AND COALESCE(ex.status,'completed') <> 'cancelled') ORDER BY o.id,ret.id,ri.id LIMIT 70"},{"name":"PROD_OCTOBER_REFUNDS","sql":"WITH goods AS (SELECT return_id,SUM(quantity) AS goods_qty FROM return_items GROUP BY return_id) SELECT o.shipping_status,COUNT(*) AS returns_count,SUM(CASE WHEN r.amount>0 AND COALESCE(g.goods_qty,0)=0 THEN 1 ELSE 0 END) AS money_only,SUM(CASE WHEN r.amount>0 AND COALESCE(g.goods_qty,0)>0 THEN 1 ELSE 0 END) AS money_plus_goods,SUM(CASE WHEN r.amount=0 AND COALESCE(g.goods_qty,0)>0 THEN 1 ELSE 0 END) AS goods_only FROM returns r JOIN orders o ON o.id=r.order_id LEFT JOIN goods g ON g.return_id=r.id WHERE r.return_date>='2026-10-01' AND r.return_date<'2026-11-01' AND COALESCE(r.status,'completed')<>'cancelled' AND NOT EXISTS(SELECT 1 FROM exchanges e WHERE e.refund_return_id=r.id AND COALESCE(e.status,'completed')<>'cancelled') GROUP BY o.shipping_status ORDER BY o.shipping_status"},{"name":"PROD_SHORTAGE_TOTALS","sql":"WITH reserve AS (SELECT inventory_source,variant_id,SUM(quantity) AS reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id), deficit AS (SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) AS physical_qty FROM reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0)) SELECT COUNT(*) AS shortage_sku_groups,COALESCE(SUM(reserved_qty-physical_qty),0) AS shortage_units FROM deficit"},{"name":"PROD_SHORTAGE_LIST","sql":"WITH reserve AS (SELECT inventory_source,variant_id,SUM(quantity) AS reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id) SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) AS physical_qty,r.reserved_qty-COALESCE(s.quantity,0) AS shortage_units FROM reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0) ORDER BY shortage_units DESC,r.variant_id LIMIT 60"},{"name":"PROD_1563_CASE","sql":"SELECT o.id AS order_id,o.external_id,o.shipping_status,ret.id AS return_id,ret.return_date,ri.order_item_id,oi.product_name_snapshot,oi.stock_writeoff_status,ri.quantity AS returned_qty,ri.physical_received_at,ri.inventory_source,ir.status AS reservation_status,ir.variant_id,ir.quantity AS reservation_qty FROM returns ret JOIN orders o ON o.id=ret.order_id LEFT JOIN return_items ri ON ri.return_id=ret.id LEFT JOIN order_items oi ON oi.id=ri.order_item_id LEFT JOIN inventory_reservations ir ON ir.order_item_id=ri.order_item_id WHERE o.id=1563 ORDER BY ret.id,ri.id LIMIT 40"}]
queries.push(...[{"name":"PROD_1563_LAST_STOCK_CHECKS","sql":"SELECT c.id,c.inventory_source,c.variant_id,c.checked_at,c.reference_type,c.reference_id,c.check_type,c.expected_quantity,c.counted_quantity FROM inventory_stock_checks c WHERE c.variant_id IN (212,853,1444,1302,1437) AND c.checked_at >= '2026-10-02' ORDER BY c.checked_at DESC LIMIT 65"},{"name":"PROD_1563_STOCK_RESERVATION_AGGREGATES","sql":"SELECT s.id,s.inventory_source,s.variant_id,s.quantity,s.reserved_quantity AS cached_reserved,(SELECT COALESCE(SUM(r.quantity),0) FROM inventory_reservations r WHERE r.inventory_source=s.inventory_source AND r.variant_id=s.variant_id AND r.status='active') AS actual_reserved,s.updated_at FROM inventory_stock s WHERE (s.inventory_source='boutique' AND s.variant_id=212) OR (s.inventory_source='warehouse' AND s.variant_id IN (1444,853)) ORDER BY s.variant_id"},{"name":"PROD_1563_ALL_RETURN_COVERAGE","sql":"SELECT oi.id,oi.product_name_snapshot,oi.quantity AS ordered_qty,COALESCE((SELECT SUM(ri.quantity) FROM return_items ri JOIN returns r ON r.id=ri.return_id WHERE ri.order_item_id=oi.id AND r.order_id=oi.order_id AND COALESCE(r.status,'completed')<>'cancelled' AND NOT EXISTS(SELECT 1 FROM exchanges e WHERE e.refund_return_id=r.id AND COALESCE(e.status,'completed')<>'cancelled')),0) AS returned_qty,ir.id AS reserve_id,ir.status AS reserve_status,ir.quantity AS reserved_qty,ir.inventory_source,ir.variant_id FROM order_items oi LEFT JOIN inventory_reservations ir ON ir.order_item_id=oi.id WHERE oi.order_id=1563 ORDER BY oi.id"},{"name":"PROD_1563_OPEN_EXCHANGES","sql":"SELECT id,status,exchange_date FROM exchanges WHERE order_id=1563 ORDER BY id"},{"name":"PROD_1563_ORDER_STATE","sql":"SELECT id,external_id,shipping_status,order_status,return_amount,received_amount,total_amount,updated_at FROM orders WHERE id=1563"}])
queries.push(...[{"name":"PROD_DEFICIT_SOURCE_AND_SKU","sql":"WITH active_reserve AS (SELECT inventory_source,variant_id,SUM(quantity) reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id), deficit AS (SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) physical_qty FROM active_reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0)) SELECT d.inventory_source,d.variant_id,COALESCE(p.name,s.product_name_snapshot,'?') AS product_name,COALESCE(v.gender,s.gender_snapshot) AS gender,COALESCE(v.color,s.color_snapshot) AS color,COALESCE(v.material,s.material_snapshot) AS material,COALESCE(v.length,s.length_snapshot) AS length,COALESCE(v.size_label,s.size_snapshot) AS size,d.physical_qty,d.reserved_qty,d.reserved_qty-d.physical_qty AS gap,COALESCE(opposite.quantity,0) AS opposite_source_physical,COALESCE(opposite.reserved_quantity,0) AS opposite_reserved,s.updated_at AS stock_updated_at,s.last_action,s.last_source_ref FROM deficit d LEFT JOIN inventory_stock s ON s.inventory_source=d.inventory_source AND s.variant_id=d.variant_id LEFT JOIN inventory_stock opposite ON opposite.inventory_source=CASE d.inventory_source WHEN 'warehouse' THEN 'boutique' ELSE 'warehouse' END AND opposite.variant_id=d.variant_id LEFT JOIN catalog_variants v ON v.id=d.variant_id LEFT JOIN catalog_products p ON p.id=v.product_id ORDER BY gap DESC,d.variant_id LIMIT 75"},{"name":"PROD_DEFICIT_ORDER_LINES","sql":"WITH active_reserve AS (SELECT inventory_source,variant_id,SUM(quantity) reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id), deficit AS (SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) physical_qty FROM active_reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0)) SELECT d.inventory_source,d.variant_id,d.physical_qty,d.reserved_qty,o.id AS order_id,o.external_id,o.order_date,o.created_at AS order_created,o.order_status,o.shipping_status,o.shipping_date,oi.id AS item_id,oi.product_name_snapshot,oi.quantity AS order_item_quantity,oi.stock_writeoff_status,r.id AS reservation_id,r.quantity AS reservation_quantity,r.created_at AS reservation_created,r.updated_at AS reservation_updated,r.status,r.reference_type,r.reference_id,(SELECT COUNT(*) FROM return_items ri JOIN returns ret ON ret.id=ri.return_id WHERE ri.order_item_id=oi.id AND COALESCE(ret.status,'completed')<>'cancelled') AS returns_count FROM deficit d JOIN inventory_reservations r ON r.inventory_source=d.inventory_source AND r.variant_id=d.variant_id AND r.status='active' JOIN orders o ON o.id=r.order_id JOIN order_items oi ON oi.id=r.order_item_id ORDER BY d.variant_id,r.created_at,r.id LIMIT 120"},{"name":"PROD_DEFICIT_LATEST_PHYSICAL_CHECKS","sql":"WITH active_reserve AS (SELECT inventory_source,variant_id,SUM(quantity) reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id), deficit AS (SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) physical_qty FROM active_reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0)), recent_check AS (SELECT d.inventory_source,d.variant_id,d.physical_qty,d.reserved_qty,c.id AS check_id,c.checked_at,c.check_type,c.expected_quantity,c.counted_quantity,c.reserved_quantity AS checked_reserved,c.reference_type,c.reference_id,ROW_NUMBER() OVER(PARTITION BY d.inventory_source,d.variant_id ORDER BY c.checked_at DESC,c.id DESC) AS rank FROM deficit d LEFT JOIN inventory_stock_checks c ON c.inventory_source=d.inventory_source AND c.variant_id=d.variant_id) SELECT * FROM recent_check WHERE rank<=3 ORDER BY variant_id,inventory_source,rank LIMIT 80"},{"name":"PROD_DEFICIT_RECENT_MOVEMENTS","sql":"WITH active_reserve AS (SELECT inventory_source,variant_id,SUM(quantity) reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id), deficit AS (SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) physical_qty FROM active_reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0)), numbered AS (SELECT d.inventory_source,d.variant_id,m.id,m.created_at,m.movement_type,m.quantity_delta,m.quantity_after,m.reference_type,m.reference_id,ROW_NUMBER() OVER(PARTITION BY d.inventory_source,d.variant_id ORDER BY m.created_at DESC,m.id DESC) AS rank FROM deficit d JOIN inventory_movements m ON m.inventory_source=d.inventory_source AND m.variant_id=d.variant_id) SELECT * FROM numbered WHERE rank<=7 ORDER BY variant_id,inventory_source,rank LIMIT 100"},{"name":"PROD_DEFICIT_RESERVED_CACHE","sql":"SELECT s.inventory_source,s.variant_id,COUNT(*) AS stock_rows,SUM(s.reserved_quantity) AS cached_reserved,(SELECT COALESCE(SUM(r.quantity),0) FROM inventory_reservations r WHERE r.inventory_source=s.inventory_source AND r.variant_id=s.variant_id AND r.status='active') AS actual_reserved FROM inventory_stock s WHERE s.variant_id IS NOT NULL GROUP BY s.inventory_source,s.variant_id HAVING COUNT(*)>1 OR SUM(s.reserved_quantity)<>(SELECT COALESCE(SUM(r.quantity),0) FROM inventory_reservations r WHERE r.inventory_source=s.inventory_source AND r.variant_id=s.variant_id AND r.status='active') ORDER BY ABS(cached_reserved-actual_reserved) DESC LIMIT 80"},{"name":"PROD_DEFICIT_RESERVES_AFTER_CHECK","sql":"WITH active_reserve AS (SELECT inventory_source,variant_id,SUM(quantity) reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id), deficit AS (SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) physical_qty FROM active_reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0)) SELECT d.inventory_source,d.variant_id,r.id AS reservation_id,r.order_id,r.order_item_id,r.quantity,r.created_at AS reserved_at,(SELECT MAX(c.checked_at) FROM inventory_stock_checks c WHERE c.inventory_source=d.inventory_source AND c.variant_id=d.variant_id AND c.checked_at<=r.created_at) AS last_physical_check_before_reservation,(SELECT MIN(c.checked_at) FROM inventory_stock_checks c WHERE c.inventory_source=d.inventory_source AND c.variant_id=d.variant_id AND c.checked_at>r.created_at) AS first_physical_check_after_reservation,(SELECT COUNT(*) FROM inventory_movements m WHERE m.inventory_source=d.inventory_source AND m.variant_id=d.variant_id AND m.created_at>r.created_at) AS later_movement_count FROM deficit d JOIN inventory_reservations r ON r.inventory_source=d.inventory_source AND r.variant_id=d.variant_id AND r.status='active' ORDER BY d.variant_id,r.created_at LIMIT 100"}])
queries.push(...[{"name":"PROD_DEFICIT_STOCK_AT_RESERVATION","sql":"WITH reserve AS (SELECT inventory_source,variant_id,SUM(quantity) AS reserved_qty FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id), deficit AS (SELECT r.inventory_source,r.variant_id,r.reserved_qty,COALESCE(s.quantity,0) AS physical_qty FROM reserve r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0)) SELECT d.inventory_source,d.variant_id,r.order_id,r.id AS reservation_id,r.order_item_id,r.quantity AS reserved_qty,r.created_at AS reservation_created,(SELECT m.quantity_after FROM inventory_movements m WHERE m.inventory_source=r.inventory_source AND m.variant_id=r.variant_id AND m.created_at<=r.created_at ORDER BY m.created_at DESC,m.id DESC LIMIT 1) AS physical_snapshot_before_reservation,(SELECT m.movement_type FROM inventory_movements m WHERE m.inventory_source=r.inventory_source AND m.variant_id=r.variant_id AND m.created_at<=r.created_at ORDER BY m.created_at DESC,m.id DESC LIMIT 1) AS previous_movement_type,(SELECT m.created_at FROM inventory_movements m WHERE m.inventory_source=r.inventory_source AND m.variant_id=r.variant_id AND m.created_at<=r.created_at ORDER BY m.created_at DESC,m.id DESC LIMIT 1) AS previous_movement_time,(SELECT m.quantity_after FROM inventory_movements m WHERE m.inventory_source=r.inventory_source AND m.variant_id=r.variant_id AND m.created_at>r.created_at ORDER BY m.created_at ASC,m.id ASC LIMIT 1) AS first_later_physical_after,(SELECT m.movement_type FROM inventory_movements m WHERE m.inventory_source=r.inventory_source AND m.variant_id=r.variant_id AND m.created_at>r.created_at ORDER BY m.created_at ASC,m.id ASC LIMIT 1) AS first_later_movement_type,(SELECT m.created_at FROM inventory_movements m WHERE m.inventory_source=r.inventory_source AND m.variant_id=r.variant_id AND m.created_at>r.created_at ORDER BY m.created_at ASC,m.id ASC LIMIT 1) AS first_later_movement_time FROM deficit d JOIN inventory_reservations r ON r.inventory_source=d.inventory_source AND r.variant_id=d.variant_id AND r.status='active' ORDER BY r.order_id,d.variant_id,r.id LIMIT 100"},{"name":"PROD_ORDER_2177_STOCK_AND_ACTIVITY","sql":"SELECT m.inventory_source,m.variant_id,m.created_at,m.movement_type,m.quantity_delta,m.quantity_after,m.reference_type,m.reference_id FROM inventory_movements m WHERE m.variant_id IN (131,240,662,1939) AND m.created_at>='2026-10-24' ORDER BY m.created_at,m.id LIMIT 100"},{"name":"PROD_DEFICIT_ACTIVITY_BY_ORDERS","sql":"SELECT o.id AS order_id,o.external_id,o.order_date,o.shipping_status,o.order_status,COUNT(DISTINCT r.id) AS active_reservations,SUM(r.quantity) AS reserved_units,MIN(r.created_at) AS earliest_reservation,MAX(r.created_at) AS latest_reservation FROM inventory_reservations r JOIN orders o ON o.id=r.order_id WHERE r.status='active' AND o.id IN (2177,2138,943,2182,1118,1417,1972,1540) GROUP BY o.id ORDER BY latest_reservation DESC"}])
for (const {name,sql} of queries){
 assert(/^\s*(?:SELECT|WITH)\b/i.test(sql) && !sql.includes(';') && !/\b(?:INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|REPLACE|PRAGMA|ATTACH|VACUUM|MERGE)\b/i.test(sql),'Only SELECT allowed')
 const r=await fetch(base+'/query',{method:'POST',headers,body:JSON.stringify({sql}),signal:AbortSignal.timeout(30000)})
 const data=await r.json()
 if(!r.ok||!data.success)throw Error(name+' failed: '+JSON.stringify({status:r.status,codes:(data.errors||[]).map(x=>x.code)}))
 console.log(name+' '+JSON.stringify(data.result?.[0]?.results||[]))
}
console.log('PROD_READ_ONLY_AUDIT_COMPLETE; zero writes; no D1 changes')
